package com.folha.pdf;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.os.Build;import org.json.*;import java.net.*;import java.io.*;import java.security.*;import java.util.*;
public final class Updater {
 private static final String REPO="cristianoarakaki-cpu/Arakaki",MANIFEST="https://raw.githubusercontent.com/"+REPO+"/main/Folha/update.json";
 private final Activity activity;private final android.content.SharedPreferences prefs;private volatile boolean working;private File ready;
 Updater(Activity a){activity=a;prefs=a.getSharedPreferences("updates",0);}
 private void ui(Runnable r){activity.runOnUiThread(()->{if(!activity.isFinishing()&&!activity.isDestroyed())r.run();});}
 void menu(){boolean auto=prefs.getBoolean("automatic",true);new AlertDialog.Builder(activity).setTitle("Folha PDF 1.1.1").setItems(new String[]{"Verificar atualizações agora",(auto?"Desativar":"Ativar")+" verificação automática", "Como funciona"},(d,w)->{if(w==0)check(true);else if(w==1)prefs.edit().putBoolean("automatic",!auto).apply();else new AlertDialog.Builder(activity).setTitle("Atualizações pelo GitHub").setMessage("Ao abrir o app, verificamos novas versões a cada 6 horas, se houver internet. Você escolhe baixar. O APK é conferido pelo SHA-256 e pela assinatura instalada antes de abrir o instalador do Android. Não é feita instalação silenciosa.\n\nConversões e OCR continuam locais, sem envio de documentos.").setPositiveButton("Entendi",null).show();}).show();}
 void automatic(){if(prefs.getBoolean("automatic",true)&&System.currentTimeMillis()-prefs.getLong("last",0)>6*60*60*1000L)check(false);}
 private static HttpURLConnection connection(String value)throws Exception{URL url=new URL(value);for(int n=0;n<6;n++){String host=url.getHost();if(!"https".equals(url.getProtocol())||!(host.equals("raw.githubusercontent.com")||host.equals("github.com")||host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com")))throw new IOException("Endereço de atualização inválido.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","FolhaPDF/1.1.1");int code=c.getResponseCode();if(code>=300&&code<400){String loc=c.getHeaderField("Location");c.disconnect();if(loc==null)throw new IOException("Redirecionamento inválido.");url=new URL(url,loc);continue;}if(code!=200){c.disconnect();throw new IOException(code==404?"Canal de atualização ainda não publicado.":"Servidor indisponível ("+code+").");}return c;}throw new IOException("Muitos redirecionamentos.");}
 void check(boolean manual){if(working)return;working=true;if(manual)ui(()->android.widget.Toast.makeText(activity,"Verificando no GitHub…",0).show());new Thread(()->{try{HttpURLConnection c=connection(MANIFEST);JSONObject json;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new IOException("Resposta inválida.");out.write(b,0,n);}json=new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();}prefs.edit().putLong("last",System.currentTimeMillis()).apply();int current=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionCode;int next=json.getInt("versionCode");if(!"com.folha.pdf".equals(json.getString("packageName")))throw new IOException("Canal de outro aplicativo.");if(next<=current){if(manual)message("Você está atualizado", "Versão instalada: 1.1.1.");return;}String url=json.getString("downloadUrl"),sha=json.getString("sha256");if(!url.startsWith("https://github.com/"+REPO+"/releases/download/folha-v")||!url.endsWith("/Folha-PDF.apk")||!sha.matches("[a-fA-F0-9]{64}"))throw new IOException("Dados da atualização inválidos.");String version=json.getString("versionName"),notes=json.optString("notes", "Melhorias e correções.");ui(()->new AlertDialog.Builder(activity).setTitle("Folha PDF "+version+" disponível").setMessage(notes+"\n\nDeseja baixar e instalar esta versão?").setPositiveButton("Baixar",(d,w)->download(url,sha,next)).setNegativeButton("Agora não",null).show());}catch(Exception e){if(manual)message("Não foi possível verificar",e.getMessage()+"\nTente novamente com conexão à internet.");}finally{working=false;}}).start();}
 private void message(String title,String text){ui(()->new AlertDialog.Builder(activity).setTitle(title).setMessage(text).setPositiveButton("OK",null).show());}
 private void download(String url,String expected,int version){if(working)return;working=true;ProgressDialog progress=new ProgressDialog(activity);progress.setTitle("Baixando atualização");progress.setMessage("Aguarde. Seus documentos continuam no celular.");progress.setCancelable(false);progress.show();new Thread(()->{File tmp=null;try{File dir=new File(activity.getCacheDir(),"exports");dir.mkdirs();tmp=new File(dir,"folha-update.part");HttpURLConnection c=connection(url);MessageDigest digest=MessageDigest.getInstance("SHA-256");long total=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){total+=n;if(total>150L*1024*1024)throw new IOException("Atualização excede o limite permitido.");digest.update(b,0,n);out.write(b,0,n);}}finally{c.disconnect();}StringBuilder hex=new StringBuilder();for(byte b:digest.digest())hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(!expected.equalsIgnoreCase(hex.toString()))throw new IOException("Falha na integridade do APK. Tente baixar novamente.");PackageManager pm=activity.getPackageManager();PackageInfo incoming=pm.getPackageArchiveInfo(tmp.getAbsolutePath(),PackageManager.GET_SIGNATURES),installed=pm.getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNATURES);if(incoming==null||!installed.packageName.equals(incoming.packageName)||incoming.versionCode!=version||incoming.versionCode<=installed.versionCode||incoming.signatures==null||!new HashSet<>(Arrays.asList(installed.signatures)).equals(new HashSet<>(Arrays.asList(incoming.signatures))))throw new IOException("O APK não corresponde ao aplicativo ou à assinatura instalada.");ready=new File(dir,"Folha-PDF-update.apk");if(ready.exists()&&!ready.delete())throw new IOException("Falha ao preparar instalação.");if(!tmp.renameTo(ready))throw new IOException("Falha ao preparar instalação.");ui(()->{progress.dismiss();install();});}catch(Exception e){if(tmp!=null)tmp.delete();ui(()->{progress.dismiss();message("Atualização não concluída",e.getMessage());});}finally{working=false;}}).start();}
 void install(){if(ready==null||!ready.exists())return;if(!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle("Permitir atualização").setMessage("Autorize o Folha PDF a instalar atualizações na próxima tela. Depois volte ao app para continuar.").setPositiveButton("Abrir configurações",(d,w)->{try{activity.startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())),12);}catch(Exception e){message("Permissão necessária","Permita a instalação por este aplicativo nas configurações do Android.");}}).setNegativeButton("Cancelar",null).show();return;}try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.parse("content://com.folha.pdf.files/"+ready.getName()),"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(i);}catch(Exception e){message("Instalação não iniciada","Não foi possível abrir o instalador do Android. Tente novamente pelo menu Atualizações.");}}
}
